function wankai()
{
   if(!_parent._parent.useAI)
   {
      return _parent.ql >= 300 && _parent.kis(_parent.斩) && _parent.kis(_parent.跳);
   }
   return false;
}

functions.DefineSprite_541/frame_1/DoAction.as#doW:
function doWanKai()
{
   initCtrl();
   if(_parent.万解)
   {
      hp = _parent.中转.hp;
      ql = _parent.中转.ql;
      if(_parent._name == "p1")
      {
         trace("p1");
         _this.上 = _root.w;
         _this.下 = _root.s;
         _this.左 = _root.a;
         _this.右 = _root.d;
         _this.斩 = _root.j;
         _this.跳 = _root.k;
         _this.冲 = _root.l;
         _this.招 = _root.u;
         _this.必杀 = _root.i;
         _this.换 = _root.o;
      }
      else
      {
         trace("p2");
         _this.上 = _root.上箭;
         _this.下 = _root.下箭;
         _this.左 = _root.左箭;
         _this.右 = _root.右箭;
         _this.斩 = _root.N1;
         _this.跳 = _root.N2;
         _this.冲 = _root.N3;
         _this.招 = _root.N4;
         _this.必杀 = _root.N5;
         _this.换 = _root.N6;
      }
      gotoAndStop("开场");
      play();
   }
}

functions.DefineSprite_541/frame_1/DoAction.as#ini:
function initCtrl()
{
   if(_parent.useAI == undefined)
   {
      return undefined;
   }
   trace("initCtrl: " + _parent.useAI);
   _parent.updateGJL();
   _root.game["p" + pn].updateGJL();
   if(_parent.useAI)
   {
      AImain.gotoAndStop(2);
      _root.airanset = setInterval(randAI,500);
   }
   else
   {
      AImain.gotoAndStop(1);
      AImain.unloadMovie();
   }
}

functions.DefineSprite_541/frame_1/DoAction.as#wan:
function wankai()
{
   _parent.万解 = true;
   _parent.中转.ql = ql;
   _parent.中转.hp = hp;
   if(!wudi)
   {
      clearInterval(_root.feiint);
      _root.feiint = setInterval(feixue,1000);
   }
   _parent.nextFrame();
   _root._y = 0;
}
